<template><div class="login-page flex flex-center"><q-card class="login-card"><div class="login-card__brand"><h1 class="login-card__title">เปลี่ยนรหัสผ่าน</h1></div><q-form class="login-card__form" @submit.prevent="submit"><q-input v-model="current" type="password" label="รหัสผ่านปัจจุบัน" outlined /><q-input v-model="password" type="password" label="รหัสผ่านใหม่" outlined /><q-input v-model="confirm" type="password" label="ยืนยันรหัสผ่านใหม่" outlined /><q-banner v-if="message" dense rounded :class="success?'bg-positive text-white':'login-card__error'">{{ message }}</q-banner><q-btn type="submit" unelevated no-caps label="เปลี่ยนรหัสผ่าน" :loading="loading" class="login-card__submit" /></q-form></q-card></div></template>
<script setup lang="ts">import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { authApiService } from '@/services/auth-api.service'; import { useAuthStore } from '@/stores/auth-store'; const router=useRouter(),auth=useAuthStore(),current=ref(''),password=ref(''),confirm=ref(''),loading=ref(false),message=ref(''),success=ref(false); async function submit(){if(password.value.length<8||password.value!==confirm.value){message.value='รหัสผ่านต้องตรงกันและมีอย่างน้อย 8 ตัวอักษร';return;}loading.value=true;try{await authApiService.changePassword(current.value,password.value);await auth.logout();success.value=true;message.value='เปลี่ยนรหัสผ่านแล้ว';setTimeout(()=>void router.replace('/admin/login'),1000);}catch{message.value='รหัสผ่านปัจจุบันไม่ถูกต้อง';}finally{loading.value=false;}}</script>
